fh .lfh-panel-leave-to {\n  opacity: 0;\n  transform: translateY(-6px);\n}\n.lfh .lfh-areas .lfh-grid:not(.is-single-row) {\n  margin-top: 18px;\n}\n.lfh .lfh-button {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  height: 34px;\n  padding: 0 14px;\n  border: 1px solid var(--lfh-border);\n  border-radius: 17px;\n  background: var(--lfh-chip);\n  color: var(--lfh-text);\n  font-size: 13px;\n  text-decoration: none;\n  white-space: nowrap;\n  cursor: pointer;\n  transition: background-color 0.2s ease, transform 0.2s ease;\n}\n.lfh .lfh-button:hover:not(:disabled) {\n  background: var(--lfh-chip-hover);\n}\n.lfh .lfh-button:active:not(:disabled) {\n  transform: scale(0.97);\n}\n.lfh .lfh-button:disabled {\n  opacity: 0.45;\n  cursor: default;\n}\n.lfh .lfh-button.is-icon {\n  width: 34px;\n  padding: 0;\n}\n.lfh .lfh-button.is-wide {\n  min-width: 220px;\n  height: 40px;\n  border-radius: 20px;\n}\n.lfh .lfh-spin-on-hover {\n  transition: transform 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);\n}\n.lfh .lfh-button:hover .lfh-spin-on-hover {\n  transform: rotate(1turn);\n}\n.lfh .lfh-spinning {\n  animation: lfh-spin 0.8s linear infinite;\n}\n.lfh .lfh-spinner {\n  width: 15px;\n  height: 15px;\n  box-sizing: border-box;\n  border-radius: 50%;\n  border: 2px solid var(--lfh-chip-hover);\n  border-top-color: var(--theme-color);\n  animation: lfh-spin 0.7s linear infinite;\n}\n.lfh .lfh-segmented {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n  padding: 3px;\n  border-radius: 12px;\n  background: var(--lfh-chip);\n}\n.lfh .lfh-segmented-item {\n  height: 28px;\n  padding: 0 11px;\n  border: none;\n  border-radius: 9px;\n  background: transparent;\n  color: var(--lfh-muted);\n  font-size: 13px;\n  white-space: nowrap;\n  cursor: pointer;\n  transition: background-color 0.2s ease, color 0.2s ease, box-shadow 0.2s ease;\n}\n.lfh .lfh-segmented-item:hover {\n  color: var(--lfh-text);\n}\n.lfh .lfh-segmented-item.selected {\n  ba